'use strict';

// The two guides written for teachers were linked from one page on the whole
// site. The React teacher pages now link them (src/pages/Class/
// teacherGuideLinks.test.js checks that half). This checks the half a crawler
// reads: the same lines on /teach, /teach/plans and /schools, and nothing
// generated by this script carrying an em dash, which reads as machine-made.

const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const path = require('path');
const { PAGES, renderRouteDocument } = require('./generate-static-seo');

const page = (route) => PAGES.find((p) => p.route === route);
const TEMPLATE = `<!doctype html><html><head>
  <title>Home</title>
  <meta name="description" content="home" />
  <link rel="canonical" href="https://codeitlearn.com/" />
  <meta property="og:url" content="https://codeitlearn.com/" />
  <meta property="og:title" content="Home" />
  <meta property="og:description" content="home" />
  <meta name="twitter:title" content="Home" />
  <meta name="twitter:description" content="home" />
</head><body><div id="root"><main>homepage fallback</main></div></body></html>`;

test('the teacher pages a crawler reads link the teacher guides', () => {
  const expected = {
    '/teach': ['/guide/cs-education-week-coding-hour'],
    '/teach/plans': ['/guide/cs-education-week-coding-hour'],
    '/schools': ['/guide/cs-education-week-coding-hour', '/guide/glitch-for-classrooms'],
  };
  for (const [route, hrefs] of Object.entries(expected)) {
    const html = renderRouteDocument(TEMPLATE, page(route));
    for (const href of hrefs) {
      assert.ok(html.includes(`<a href="${href}">`), `${route} does not link ${href} in its crawlable copy`);
    }
  }
});

test('no string this generator publishes carries an em dash', () => {
  // Comments may; quoted words from other sites live in the guides, not here.
  const source = fs.readFileSync(path.join(__dirname, 'generate-static-seo.js'), 'utf8');
  const found = source.split('\n')
    .map((line, i) => ({ line, n: i + 1 }))
    .filter(({ line }) => !/^\s*(\/\/|\*|\/\*)/.test(line) && /—/.test(line))
    .map(({ line, n }) => `line ${n}: ${line.trim().slice(0, 80)}`);
  assert.deepEqual(found, []);
});
